code='''def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    separator_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1 and row[0] != background]
    separator_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]
    row_bounds = [-1] + separator_rows + [h]
    col_bounds = [-1] + separator_cols + [w]
    panels = []
    for ri in range(len(row_bounds) - 1):
        r0, r1 = row_bounds[ri] + 1, row_bounds[ri + 1]
        if r0 >= r1:
            continue
        for ci in range(len(col_bounds) - 1):
            c0, c1 = col_bounds[ci] + 1, col_bounds[ci + 1]
            if c0 >= c1:
                continue
            pattern = [(r-r0, c-c0, grid[r][c])
                       for r in range(r0, r1) for c in range(c0, c1)
                       if grid[r][c] != background]
            panels.append((r0, r1, c0, c1, pattern))
    source = next((panel for panel in panels if panel[4]), None)
    if source is None:
        return [row[:] for row in grid]
    pattern = source[4]
    out = [[background for _ in range(w)] for _ in range(h)]
    for r in separator_rows:
        out[r] = grid[r][:]
    for c in separator_cols:
        for r in range(h):
            out[r][c] = grid[r][c]
    for r0, r1, c0, c1, _ in panels:
        for dr, dc, value in pattern:
            if dr < r1-r0 and dc < c1-c0:
                out[r0+dr][c0+dc] = value
    return out
'''
